args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?composer ?composerLabel ?deathPlace ?deathPlaceLabel WHERE {
  VALUES ?composer { dbr:Isaac_Schwartz }
  OPTIONAL { ?composer dbo:deathPlace ?deathPlace . }
  OPTIONAL { ?composer dbp:deathPlace ?deathPlace . }
  OPTIONAL { ?composer dbp:placeOfDeath ?deathPlace . }
  OPTIONAL { ?composer dbp:place_of_death ?deathPlace . }
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = 'en') }
  OPTIONAL { ?composer rdfs:label ?composerLabel . FILTER(lang(?composerLabel) = 'en') }
}

